$delivery = DataFrame::fromRows([['sku' =&gt; 'B2', 'qty' =&gt; 12], ['sku' =&gt; 'D4', 'qty' =&gt; 3]]);

echo phplyr($stock)-&gt;rowsUpsert($delivery, by: 'sku');
